        adaptiveFormAndInteractiveCommunicationWebChannelConfiguration(
            
            bool post
            , 
            
            bool apply
            , 
            
            bool r_delete
            , 
            
            std::string action
            , 
            
            std::string Dollarlocation
            , 
            std::list<std::string> propertylist
            
            , 
            
            bool showPlaceholder
            , 
            
            int maximumCacheEntries
            , 
            
            std::string afPeriodscriptingPeriodcompatversion
            , 
            
            bool makeFileNameUnique
            , 
            
            bool generatingCompliantData
            
        )
        {
            std::string url = basepath + "/system/console/configMgr/Adaptive Form and Interactive Communication Web Channel Configuration"; //


            // Headers  | 

            // Query    | post apply r_delete action Dollarlocation propertylist showPlaceholder maximumCacheEntries afPeriodscriptingPeriodcompatversion makeFileNameUnique generatingCompliantData 
            addQueryParam("post",post);
            addQueryParam("apply",apply);
            addQueryParam("delete",r_delete);
            addQueryParam("action",action);
            addQueryParam("$location",Dollarlocation);
            for (auto &x : propertylist){
                addQueryParam("propertylist", std::string(x));
            }
            addQueryParam("showPlaceholder",showPlaceholder);
            addQueryParam("maximumCacheEntries",maximumCacheEntries);
            addQueryParam("af.scripting.compatversion",afPeriodscriptingPeriodcompatversion);
            addQueryParam("makeFileNameUnique",makeFileNameUnique);
            addQueryParam("generatingCompliantData",generatingCompliantData);

            // Form     | 





            std::string payload = "";
            // Send Request
            // METHOD | POST
            // Body     | 
            int httpCode = sendRequest(url, "POST", reinterpret_cast<uint8_t*>(&payload[0]), payload.length());

            // Handle Request
            String output = getResponseBody();
            std::string output_string = output.c_str();




            AdaptiveFormAndInteractiveCommunicationWebChannelConfigurationInfo obj(output_string);


            Response<AdaptiveFormAndInteractiveCommunicationWebChannelConfigurationInfo> response(obj, httpCode);
            return response;
        }

